    private void enterNewScope() {
      scopes.push(new Scope());
    }

    private void leaveNewScope() {
      Scope scope = scopes.pop();
      for(String id:scope.varNames()) {
        VarDesc varDesc = scope.varDesc(id);
        if(varDesc != null)
          throw new SandwoodModelException("Variable " + id + " is never initialized.", varDesc.nameLocation());
      }
    }

